head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods10041";
scwin.discls_minute = 4;
scwin.discls_second = 59;
scwin.discls_timer = undefined;
scwin.findIdForm = null;
scwin.ipt_sendPhoneAuth = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.findIdForm = scwin.tx_findIdForm;
        scwin.ipt_sendPhoneAuth = scwin.tx_sendPhoneAuth;
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods10041.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_openComPop_onclick
 * @description 「회사명찾기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openComPop_onclick = async function(e){
    try {
        await scwin.openComPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10041.btn_openComPop_onclick' }); }
};

/**
 * @method
 * @name chkBtn_onclick
 * @description 「인증번호발송」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.chkBtn_onclick = async function(e){
    try {
        await scwin.confPhoneAuth()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10041.chkBtn_onclick' }); }
};

/**
 * @method
 * @name btn_findIdForm_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findIdForm_onclick = function(e){
    try {
        scwin.findIdForm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10041.btn_findIdForm_onclick' }); }
};

/**
 * @method
 * @name btn_cancelForm_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancelForm_onclick = function(e){
    try {
        scwin.cancelForm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10041.btn_cancelForm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_sendSucEndForm
 * @description send Suc End Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_sendSucEndForm = async function () {
    const sbmOptions = {
        id: "tx_sendSucEndForm",
        method: "post",
        action: "/account/disclsUserInfo.do?method=disclsUserInfo",
        ref: "dma_sendSucEndFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_findIdForm
 * @description find Id Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_findIdForm = async function () {
    const sbmOptions = {
        id: "tx_findIdForm",
        method: "post",
        action: "/account/findMyInfo.do?method=findMyInfoProc",
        ref: "dma_findIdFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_sendPhoneAuth
 * @description send Phone Auth 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_sendPhoneAuth = async function () {
    const sbmOptions = {
        id: "tx_sendPhoneAuth",
        method: "post",
        action: "/account/findMyInfo.do",
        ref: "dma_sendPhoneAuthReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openComPop
 * @description open Com Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openComPop = async function () {
    const url = '/jldfil00033/jldfil00033.xml';
    const option = "width=560,height=780,resizable=no,scrollbars=no,toolbar=no";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    scwin.setCorpInfo_recv(await $c.win.openPopup((function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), String((typeof option !== 'undefined' ? option : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); let k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "_blank", width: "560", height: "780", resizable: false, scrollbars: false, type: "pageFramePopup" }, { id: '' }) : { id: "_blank", width: "560", height: "780", resizable: false, scrollbars: false, type: "pageFramePopup" }), { method: "searchSubcomForm" }));
    return;
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} comNm comNm
 * @param {*} returnKey returnKey
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, comNm, returnKey) {
    $c.util.getComponent('ipt_corpNm_2').setValue(comNm);
    $c.util.getComponent('ipt_isurCd_2').setValue(isurCd);
};

/**
 * @method
 * @name cancelForm
 * @description cancel Form 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancelForm = function () {
    confirmF("비밀번호 찾기를 취소 하시겠습니까?", async function() {
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/main.do). 전환 대상 화면이 확정되면 연결됩니다.');
    });
};

/**
 * @method
 * @name sendSucEndForm
 * @description send Suc End Form 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendSucEndForm = async function (data) {
    const frm = (document.endForm || { elements: [] });
    $c.util.getComponent("dma_sendSucEndFormReq").set("corpUsrNm", (console.warn("[sdd] unresolved:dmap-member:" + "result @ dma_sendSucEndFormReq.result"), $c.util.getComponent('dma_sendSucEndFormReq')).corpUsrNm);
    $c.util.getComponent("dma_sendSucEndFormReq").set("corpNm", (console.warn("[sdd] unresolved:dmap-member:" + "result @ dma_sendSucEndFormReq.result"), $c.util.getComponent('dma_sendSucEndFormReq')).corpNm);
    $c.util.getComponent("dma_sendSucEndFormReq").set("isurCd", (console.warn("[sdd] unresolved:dmap-member:" + "result @ dma_sendSucEndFormReq.result"), $c.util.getComponent('dma_sendSucEndFormReq')).isurCd);
    $c.util.getComponent("dma_sendSucEndFormReq").set("usrId", (console.warn("[sdd] unresolved:dmap-member:" + "result @ dma_sendSucEndFormReq.result"), $c.util.getComponent('dma_sendSucEndFormReq')).usrId);
    $c.util.getComponent('dma_sendSucEndFormReq').set('result', (console.warn("[sdd] unresolved:dmap-member:" + "result @ dma_sendSucEndFormReq.result"), $c.util.getComponent('dma_sendSucEndFormReq')).result);
    $c.util.getComponent('dma_sendSucEndFormReq').set('mode', "pw");
    await scwin.tx_sendSucEndForm();
};

/**
 * @method
 * @name confPhoneAuth
 * @description conf Phone Auth 처리
 * @returns {void}
 * @hidden N
 */
scwin.confPhoneAuth = async function () {
    const frm = (document.sendForm || { elements: [] });
    const isurCd = $c.util.getComponent('ipt_isurCd_2');
    const corpUsrNm = $c.util.getComponent('ipt_corpUsrNm_2');
    const usrId = $c.util.getComponent('ipt_usrId_2');
    const corpNm = $c.util.getComponent('ipt_corpNm_2');
    if (await scwin.checkRequired(isurCd)) {
        return;
    }
    if (await scwin.checkRequired(corpNm)) {
        return;
    }
    if (await scwin.checkRequired(usrId)) {
        return;
    }
    if (await scwin.checkRequired(corpUsrNm)) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_email1'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    confirmF("인증번호를 발송하시겠습니까?", ipt_sendPhoneAuth);
};

/**
 * @method
 * @name startTimer2
 * @description start Timer2 처리
 * @returns {void}
 * @hidden N
 */
scwin.startTimer2 = function () {
    scwin.discls_timer = setInterval(async function() {
            if (scwin.discls_second === 0) {
                scwin.discls_minute = scwin.discls_minute - 1;
                scwin.discls_second = 60;
            }
            scwin.discls_second = scwin.discls_second - 1;
            if (scwin.discls_minute <= 0 && scwin.discls_second <= 0) {
                clearInterval(scwin.discls_timer);
                await alertE("휴대폰 인증번호 입력시간(5분)이 초과되었습니다.\n재시도 하십시오.");
            }
            $c.util.getComponent('txt_areaSessionTimer2').setLabel(scwin.discls_minute + ":" + ((scwin.discls_second + "").length === 1 ? '0' + scwin.discls_second : scwin.discls_second));
        }, 1000);
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};
